    public static GameApiModuleDescriptor? TryGetModule(string gameTypeName)
    {
        if (string.IsNullOrWhiteSpace(gameTypeName)) return null;
        foreach (var m in Modules)
            if (string.Equals(m.GameTypeName, gameTypeName, StringComparison.Ordinal)) return m;
        return null;
    }
